-- sources: schema delta for an existing CDS database.
--
-- Adds the sources table of dbscripts/postgres.sql, and nothing else. Purely
-- additive, so it can run against a live database.
--
-- Re-runnable. Every statement is guarded, so applying it twice is a no-op.

BEGIN;

-- The data sources an organization registers. source_id is generated by CDS, and a
-- name is unique within an organization.
CREATE TABLE IF NOT EXISTS sources
(
    id          SERIAL PRIMARY KEY,
    source_id   VARCHAR(36)   UNIQUE NOT NULL,
    org_id      VARCHAR(255)  NOT NULL,
    name        VARCHAR(255)  NOT NULL,
    description VARCHAR(1024),
    icon_url    VARCHAR(2048) NOT NULL,
    created_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
    CONSTRAINT uq_sources_org_id_name UNIQUE (org_id, name)
);

COMMIT;
